export type CorpusReview = {
  repo: string;
  sessions: number;
  setups: number;
  costUsd: number | null;
  suspect: string | null;
  replayed: number;
  promoted: string | null;
};

export type CorpusTable = {
  rows: CorpusReview[];
  totals: {
    repos: number;
    sessions: number;
    costUsd: number | null;
    replayed: number;
    promotions: number;
  };
};

export function buildCorpusTable(reviews: CorpusReview[]): CorpusTable {
  const rows = [...reviews].sort(
    (a, b) => b.sessions - a.sessions || (a.repo < b.repo ? -1 : a.repo > b.repo ? 1 : 0),
  );
  const costs = rows.map((r) => r.costUsd).filter((c): c is number => c !== null);
  return {
    rows,
    totals: {
      repos: rows.length,
      sessions: rows.reduce((s, r) => s + r.sessions, 0),
      costUsd: costs.length ? costs.reduce((s, c) => s + c, 0) : null,
      replayed: rows.reduce((s, r) => s + r.replayed, 0),
      promotions: rows.filter((r) => r.promoted !== null).length,
    },
  };
}
EOF
cat > tests/corpus-table.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { buildCorpusTable } from "../src/review/corpus-table";

const r = (repo: string, sessions: number, costUsd: number | null, promoted: string | null = null, replayed = 1) => ({
  repo, sessions, setups: 2, costUsd, suspect: null, replayed, promoted,
});

test("sorts by sessions desc then repo", () => {
  const t = buildCorpusTable([r("b", 3, 1), r("a", 3, 1), r("c", 9, 1)]);
  expect(t.rows.map((x) => x.repo)).toEqual(["c", "a", "b"]);
});

test("totals equal sums of rows", () => {
  const t = buildCorpusTable([r("a", 3, 1.5, "B"), r("b", 4, null, null, 2), r("c", 5, 2.25, "E")]);
  expect(t.totals.repos).toBe(t.rows.length);
  expect(t.totals.sessions).toBe(t.rows.reduce((s, x) => s + x.sessions, 0));
  expect(t.totals.replayed).toBe(t.rows.reduce((s, x) => s + x.replayed, 0));
  expect(t.totals.costUsd).toBe(3.75);
  expect(t.totals.promotions).toBe(2);
});

test("costUsd null only if every row null; empty input", () => {
  expect(buildCorpusTable([r("a", 1, null)]).totals.costUsd).toBeNull();
  const e = buildCorpusTable([]);
  expect(e.totals).toEqual({ repos: 0, sessions: 0, costUsd: null, replayed: 0, promotions: 0 });
});
EOF
bun test tests/corpus-table.test.ts 2>&1 | tail -8; bun run typecheck 2>&1 | tail -3; bun test 2>&1 | tail -4

